<?php

declare(strict_types=1);

namespace SqlSemantics\Schema\Column;

/**
 * IdentityMode alternatives.
 *
 * @visibility public
 * @example Classifying the identity override policy
 *     $table = (new \SqlSemantics\SchemaBuilder(\SqlSemantics\Dialect::PostgreSql))->build('CREATE TABLE t(a INTEGER GENERATED ALWAYS AS IDENTITY, b INTEGER GENERATED BY DEFAULT AS IDENTITY)')->tables[0];
 *     $table->columns[0]->generation->mode // => \SqlSemantics\Schema\Column\IdentityMode::Always
 *     $table->columns[1]->generation->mode // => \SqlSemantics\Schema\Column\IdentityMode::ByDefault
 */
enum IdentityMode: string
{
    case Always = 'always';
    case ByDefault = 'by-default';
}
